select b.po_no ,a.client_no ,c.client_name ,e.member_nm as manager_name ,d1.code_nm as prodType ,d.code_nm as orderType ,b.item_cd ,i.item_name ,b.qty ,b.unit_price ,b.supply_price ,b.delivery_req_date ,0 as outQty ,d2.code_nm as statusTypeName ,a.contract_id from tb_contract_mst a inner join tb_contract_item b on a.contract_id = b.contract_id inner join tb_item_mst i on i.item_cd = b.item_cd left join tb_client_mst c on c.client_id = a.client_id left join tb_common_code d on b.order_type = d.code and d.com_type_cd = 'order_type' left join tb_common_code d1 on i.item_grp2 = d1.code and d1.com_type_cd = 'ITEM_GRP2' left join tb_common_code d2 on b.status_type = d2.code and d2.com_type_cd = 'status_type' left join tb_users e on e.user_id = a.manager_id where 1=1
and a.contract_date between #{strDate} and #{endDate}
and b.delivery_req_date = #{deliveryReqDate}
and c.client_name like '%' + #{clientName} + '%'
and e.member_nm like '%' + #{managerName} + '%'
and b.prod_type = #{prodType}
and b.order_type = #{orderType}
and b.item_cd like '%' + #{itemCd} + '%'
and i.item_name like '%' + #{itemName} + '%'
and b.status_type = #{statusType}
order by a.contract_date desc, a.seq desc

