UPDATE tb_contract_item
SET    order_type   = #{orderType}
      ,delivery_req_date = #{deliveryReqDate}
      ,qty          = #{qty}
      ,unit_price   = #{unitPrice}
      ,supply_price = #{supplyPrice}
      ,vat_price    = #{vatPrice}
      ,status_type  = #{statusType}
      ,etc          = #{etc}
      ,upd_id       = #{userId}
      ,upd_dt       = GETDATE()
WHERE contract_item_id = #{contractItemId}

mapper.select:
WITH bs AS ( /* ========================================================= 자급계획 S - seq = 1 수량 전체 합계 - 날짜는 가장 빠른 plan_date ========================================================= */ SELECT po_no ,MIN(plan_date) AS bs_plan_date ,SUM(ISNULL(qty, 0)) AS qty FROM tb_order_plan_type WHERE type_cd = 'S' AND seq = 1 GROUP BY po_no ),
bj AS ( /* ========================================================= 부자재계획 J - seq = 1 수량 전체 합계 - 날짜는 가장 빠른 plan_date ========================================================= */ SELECT po_no ,MIN(plan_date) AS bj_plan_date ,SUM(ISNULL(qty, 0)) AS qty FROM tb_order_plan_type WHERE type_cd = 'J' AND seq = 1 GROUP BY po_no ),
/* ========================================================= 기타계획 O ========================================================= */ op_rank AS ( SELECT po_no ,plan_date ,qty ,ROW_NUMBER() OVER ( PARTITION BY po_no ORDER BY plan_date ) AS rn FROM ( SELECT po_no ,plan_date ,SUM(ISNULL(qty, 0)) AS qty FROM tb_order_plan_type WHERE type_cd = 'O' GROUP BY po_no ,plan_date ) a ),
op AS ( SELECT po_no ,plan_date AS out_Plan_Date ,qty FROM op_rank WHERE rn = 1 ),
/* ========================================================= 생산일자 ========================================================= */ work_date AS ( SELECT po_no
,MIN( CASE WHEN proc_cd = 'PRC001' THEN prod_date END ) AS weigh_prod_date
,MIN( CASE WHEN proc_cd = 'PRC002' THEN prod_date END ) AS mat_prod_date
,MIN( CASE WHEN proc_cd = 'PRC005' THEN prod_date END ) AS packing_prod_date
FROM TB_WORK_ORDER_PROC
WHERE proc_cd IN ( 'PRC001' ,'PRC002' ,'PRC005' )
GROUP BY po_no ),
/* ========================================================= 칭량 LOT 수 ========================================================= */ weigh_qty AS ( SELECT a.po_no ,COUNT(b.lot_no) AS weigh_prod_qty FROM TB_WORK_ORDER_PROC a
INNER JOIN tb_work_order_batch b ON b.work_batch_id = a.work_batch_id
WHERE a.proc_cd = 'PRC001'
GROUP BY a.po_no ),
/* ========================================================= 제조 LOT 수 ========================================================= */ mat_qty AS ( SELECT a.po_no ,COUNT(b.lot_no) AS mat_prod_qty FROM TB_WORK_ORDER_PROC a
INNER JOIN tb_work_order_batch b ON b.work_batch_id = a.work_batch_id
WHERE a.proc_cd = 'PRC002'
GROUP BY a.po_no ),
/* ========================================================= 포장 생산수량 ========================================================= */ packing_qty AS ( SELECT po_no ,SUM(ISNULL(prod_qty, 0)) AS packing_prod_qty FROM TB_WORK_ORDER_PROC WHERE proc_cd = 'PRC005' GROUP BY po_no ),
/* ========================================================= PO / 창고별 현재재고 ========================================================= */ stock_storage AS ( SELECT po_no ,storage_cd ,SUM(ISNULL(qty, 0)) AS storage_qty FROM vw_inv_stock_tran WHERE item_type_cd = 'M0' GROUP BY po_no ,storage_cd HAVING SUM(ISNULL(qty, 0)) <> 0 ),
/* ========================================================= 창고 개수 + 현재재고 ========================================================= */ stock AS ( SELECT po_no ,COUNT(*) AS storage_cnt ,SUM(storage_qty) AS storage_qty FROM stock_storage GROUP BY po_no ),
/* ========================================================= 출고일 + 출고수량 ========================================================= */ shipment AS ( SELECT y.po_no ,MAX(x.shipment_req_date) AS shipment_req_date ,SUM(ISNULL(y.qty, 0)) AS shipment_qty FROM tb_shipment_mst x
INNER JOIN tb_shipment_item y ON y.shipment_id = x.shipment_id
WHERE x.shipment_yn = 'Y'
GROUP BY y.po_no ),
/* ========================================================= 기본 데이터 ========================================================= */ base AS ( SELECT b.po_no ,b.prod_type ,c.client_name ,a.manager_id ,b.item_cd ,i.item_name
/* 주문수량 */ ,ISNULL(b.qty, 0) AS qty ,b.delivery_req_date ,co.code_nm AS order_type_name
,ISNULL(ch.advance_pay_yn, 'N') AS advance_pay_yn ,ISNULL(ch.prod_sheet, 'N') AS prod_sheet ,ISNULL(ch.m1_yn, 'N') AS m1_yn ,ISNULL(ch.m2_yn, 'N') AS m2_yn
/* ===================================================== 자급계획 S seq = 1 전체 합계 / 가장 빠른 계획일 ===================================================== */ ,bs.bs_plan_date ,ISNULL(bs.qty, 0) AS bs_qty
/* ===================================================== 부자재계획 J seq = 1 전체 합계 / 가장 빠른 계획일 ===================================================== */ ,bj.bj_plan_date ,ISNULL(bj.qty, 0) AS bj_qty
/* 출고계획 */ ,op.out_Plan_Date ,ISNULL(op.qty, 0) AS out_qty
/* 생산일 */ ,wd.weigh_prod_date ,wd.mat_prod_date ,wd.packing_prod_date
/* 생산수량 */ ,ISNULL(wq.weigh_prod_qty, 0) AS weigh_prod_qty ,ISNULL(mq.mat_prod_qty, 0) AS mat_prod_qty ,ISNULL(pq.packing_prod_qty, 0) AS packing_prod_qty
/* 창고 */ ,ISNULL(st.storage_cnt, 0) AS storage_cnt ,ISNULL(st.storage_qty, 0) AS storage_qty
/* 출고 */ ,sh.shipment_req_date ,ISNULL(sh.shipment_qty, 0) AS shipment_qty
/* 상태 */ ,co2.code_nm AS status_type
/* 리드타임 */ ,DATEDIFF( DAY, a.contract_date, ISNULL( sh.shipment_req_date, CONVERT(date, GETDATE()) ) ) AS read_day
FROM tb_contract_mst a
INNER JOIN tb_contract_item b ON b.contract_id = a.contract_id
LEFT JOIN tb_client_mst c ON c.client_id = a.client_id
INNER JOIN tb_item_mst i ON i.item_cd = b.item_cd
LEFT JOIN tb_order_plan_check ch ON ch.po_no = b.po_no
LEFT JOIN bs ON bs.po_no = b.po_no
LEFT JOIN bj ON bj.po_no = b.po_no
LEFT JOIN op ON op.po_no = b.po_no
LEFT JOIN work_date wd ON wd.po_no = b.po_no
LEFT JOIN weigh_qty wq ON wq.po_no = b.po_no
LEFT JOIN mat_qty mq ON mq.po_no = b.po_no
LEFT JOIN packing_qty pq ON pq.po_no = b.po_no
LEFT JOIN stock st ON st.po_no = b.po_no
LEFT JOIN shipment sh ON sh.po_no = b.po_no
LEFT JOIN tb_common_code co ON co.code = b.order_type AND co.com_type_cd = 'order_type'
LEFT JOIN tb_common_code co2 ON co2.code = b.status_type AND co2.com_type_cd = 'status_type'
WHERE 1 = 1
AND a.contract_date >= #{strDate}
AND a.contract_date <= #{endDate}
AND b.po_no LIKE CONCAT('%', #{poNo}, '%')
AND b.prod_type = #{prodType}
AND c.client_name LIKE CONCAT('%', #{clientName}, '%')
AND a.manager_id = #{managerId}
AND b.item_cd LIKE CONCAT('%', #{itemCd}, '%')
AND i.item_name LIKE CONCAT('%', #{itemName}, '%')
AND b.status_type IN ('ING', 'END')
AND b.status_type = 'ING'
),
/* ========================================================= 화면용 2 ROW ========================================================= */ result AS (
/* ===================================================== ROW 0 실제 계획값 ===================================================== */ SELECT 0 AS rowId ,po_no ,po_no AS sort_po_no ,prod_type ,client_name ,manager_id ,item_cd ,item_name ,qty ,delivery_req_date ,order_type_name ,advance_pay_yn ,prod_sheet ,m1_yn ,m2_yn
/* 자급 계획 */ ,bs_plan_date ,ISNULL(bs_qty, 0) AS bs_qty
/* 사급 계획 */ ,bj_plan_date ,ISNULL(bj_qty, 0) AS bj_qty
/* 출고 계획 */ ,out_Plan_Date ,ISNULL(out_qty, 0) AS out_qty
/* 생산일자 */ ,CONVERT( varchar(10), weigh_prod_date, 23 ) AS weigh_prod_date
,CONVERT( varchar(10), mat_prod_date, 23 ) AS mat_prod_date
,CONVERT( varchar(10), packing_prod_date, 23 ) AS packing_prod_date
/* 창고 개수 */ ,CAST( ISNULL(storage_cnt, 0) AS varchar(50) ) AS storage_cnt
/* 출고일 */ ,CONVERT( varchar(10), shipment_req_date, 23 ) AS shipment_req_date
,status_type ,read_day
FROM base
UNION ALL
/* ===================================================== ROW 1 부족수량
부족수량 = 주문수량 - 계획수량 ===================================================== */ SELECT 1 AS rowId ,'' AS po_no ,po_no AS sort_po_no ,NULL AS prod_type ,NULL AS client_name ,NULL AS manager_id ,NULL AS item_cd ,NULL AS item_name ,NULL AS qty ,NULL AS delivery_req_date ,NULL AS order_type_name ,NULL AS advance_pay_yn ,NULL AS prod_sheet ,NULL AS m1_yn ,NULL AS m2_yn
/* ============================================= 자급 부족수량 주문수량 - seq 1 전체 계획수량 ============================================= */ ,NULL AS bs_plan_date
,CASE WHEN ISNULL(qty, 0) - ISNULL(bs_qty, 0) < 0 THEN 0 ELSE ISNULL(qty, 0) - ISNULL(bs_qty, 0) END AS bs_qty
/* ============================================= 사급 부족수량 주문수량 - seq 1 전체 계획수량 ============================================= */ ,NULL AS bj_plan_date
,CASE WHEN ISNULL(qty, 0) - ISNULL(bj_qty, 0) < 0 THEN 0 ELSE ISNULL(qty, 0) - ISNULL(bj_qty, 0) END AS bj_qty
/* ============================================= 출고 부족수량 ============================================= */ ,NULL AS out_Plan_Date
,CASE WHEN ISNULL(qty, 0) - ISNULL(out_qty, 0) < 0 THEN 0 ELSE ISNULL(qty, 0) - ISNULL(out_qty, 0) END AS out_qty
/* 칭량 LOT 수 */ ,CAST( ISNULL(weigh_prod_qty, 0) AS varchar(50) ) AS weigh_prod_date
/* 제조 LOT 수 */ ,CAST( ISNULL(mat_prod_qty, 0) AS varchar(50) ) AS mat_prod_date
/* 포장 생산수량 */ ,CAST( ISNULL(packing_prod_qty, 0) AS varchar(50) ) AS packing_prod_date
/* 현재 재고수량 */ ,CAST( ISNULL(storage_qty, 0) AS varchar(50) ) AS storage_cnt
/* 출고수량 */ ,CAST( ISNULL(shipment_qty, 0) AS varchar(50) ) AS shipment_req_date
,NULL AS status_type ,NULL AS read_day
FROM base )
/* ========================================================= 최종 조회 ========================================================= */ SELECT rowId ,po_no ,prod_type ,client_name ,manager_id ,item_cd ,item_name ,qty ,delivery_req_date ,order_type_name ,advance_pay_yn ,prod_sheet ,m1_yn ,m2_yn ,bs_plan_date ,bs_qty ,bj_plan_date ,bj_qty ,out_Plan_Date ,out_qty ,weigh_prod_date ,mat_prod_date ,packing_prod_date ,storage_cnt ,shipment_req_date ,status_type ,read_day FROM result ORDER BY sort_po_no, rowId

