mapper.update:
UPDATE tb_order_plan_type
SET  po_no     = #{poNo}
    ,seq       = #{seq}
    ,plan_date = #{planDate}
    ,item_type = #{itemType}
    ,qty       = #{qty}
    ,upd_id    = #{userId}
    ,upd_dt    = GETDATE()
WHERE order_plan_id = #{orderPlanId}
